              </span>
            ) : (
              <span className="size-5 rounded-full border border-gray-300" />
            )}
            <span className="text-sm leading-5 font-semibold text-black/87">
              {key === "a" ? "Select from a list" : "New number"}
            </span>
          </button>
        ))}
      </div>
